    store.seq += 1;
    store.ledger.push({
      seq: store.seq,
      docId: input.id,
      type: input.type,
      productId,
      warehouse,
      delta,
      before,
      after,
    });
  };

  for (const it of items) {
    if (input.type === 'in') {
      apply(it.productId, input.target as string, it.qty);
    } else if (input.type === 'out') {
      apply(it.productId, input.source as string, -it.qty);
